const input = $input.first().json;

const document_id = String(input.document_id ?? '').trim();

if (!document_id) {
  throw new Error('document_id가 없습니다.');
}

return [
  {
    json: {
      ...input,
      document_id
    }
  }
];

const results = [];

// 프로모션 기본 정보
const promotion = $('프로모션 정보 조회').first().json;

// 최종 타겟팅 규칙
const rules = $('Resolve Targeting Rules').first().json.output ?? {};


// --------------------------------
// 공통 함수
// --------------------------------
function toText(value) {
  if (value == null) return '';

  if (Array.isArray(value)) {
    return value.join(' ');
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

function normalize(value) {
  return toText(value).toLowerCase().trim();
}

function compact(value) {
  return toText(value)
    .toLowerCase()
    .replace(/\s+/g, '');
}

function containsAny(text, keywords) {
  if (!Array.isArray(keywords) || keywords.length === 0) {
    return true;
  }

  const normalizedText = normalize(text);

  return keywords.some((keyword) => {
    const k = normalize(keyword);
    return k && normalizedText.includes(k);
  });
}


// --------------------------------
// 일반적인 관심 키워드 제외
// --------------------------------
const GENERIC_KEYWORDS = [
  '기기변경',
  '구매',
  '상담',
  '휴대폰',
  '스마트폰',
  '핸드폰',
  '프로모션',
  '요금제',
  '할인',
  '혜택',
  '변경',
  '교체',
  '고객',
  '신규',
  '가입'
];

function isGenericKeyword(keyword) {
  const k = compact(keyword).replace(/관심|희망|예정/g, '');

  return (
    k.length < 2 ||
    GENERIC_KEYWORDS.some(
      (g) => k === g || k === g + '고객'
    )
  );
}


// --------------------------------
// 구조화된 자동 필터 조건 존재 여부
// --------------------------------
const deviceKeywords = Array.isArray(rules.target_device_keywords)
  ? rules.target_device_keywords
  : [];

const planKeywords = Array.isArray(rules.target_plan_keywords)
  ? rules.target_plan_keywords
  : [];

const brandKeywords = Array.isArray(rules.preferred_brand_keywords)
  ? rules.preferred_brand_keywords
  : [];

const interestKeywords = (
  Array.isArray(rules.interest_keywords)
    ? rules.interest_keywords
    : []
).filter((keyword) => !isGenericKeyword(keyword));

const hasAutomaticRule =
  rules.target_all === true ||
  rules.age_min != null ||
  rules.age_max != null ||
  rules.min_device_use_months != null ||
  deviceKeywords.length > 0 ||
  planKeywords.length > 0 ||
  brandKeywords.length > 0 ||
  interestKeywords.length > 0;


// 자동 판단 가능한 조건도 없고
// 전체 고객 대상도 아니면 자동 타겟팅하지 않음
if (!hasAutomaticRule) {
  return [];
}


// --------------------------------
// 고객별 조건 적용
// --------------------------------
for (const item of $input.all()) {
  const customer = item.json;

  // Always Output Data 등으로 빈 item이 들어오는 경우 방어
  if (!customer.customer_id) {
    continue;
  }

  const analysis = customer.analysis_data ?? {};

  let matched = true;
  const matchReasons = [];


  // --------------------------------
  // 전 고객 대상
  // --------------------------------
  if (rules.target_all === true) {
    matchReasons.push('전체 고객 대상 프로모션');
  }

  // target_all=true가 아닐 때만 세부 타겟 조건 적용
  else {

    // --------------------------------
    // 1. 최소 나이
    // --------------------------------
    if (rules.age_min != null) {
      if (
        customer.age == null ||
        Number(customer.age) < Number(rules.age_min)
      ) {
        matched = false;
      } else {
        matchReasons.push(
          `최소 연령 ${rules.age_min}세 이상 충족`
        );
      }
    }


    // --------------------------------
    // 2. 최대 나이
    // --------------------------------
    if (rules.age_max != null) {
      if (
        customer.age == null ||
        Number(customer.age) > Number(rules.age_max)
      ) {
        matched = false;
      } else {
        matchReasons.push(
          `최대 연령 ${rules.age_max}세 이하 충족`
        );
      }
    }


    // --------------------------------
    // 3. 최소 기기 사용 기간
    // --------------------------------
    if (rules.min_device_use_months != null) {
      if (
        customer.device_use_months == null ||
        Number(customer.device_use_months) <
          Number(rules.min_device_use_months)
      ) {
        matched = false;
      } else {
        matchReasons.push(
          `기기 사용 ${rules.min_device_use_months}개월 이상 충족`
        );
      }
    }


    // --------------------------------
    // 고객 관심/분석 통합 텍스트
    // --------------------------------
    const targetingText = compact(
      [
        customer.interests,
        customer.consultation_goal,
        customer.usage_pattern,
        customer.preferred_brand,

        analysis.analysis_summary,
        analysis.usage_profile,
        analysis.replacement_reason,
        analysis.preferred_product_group,
        analysis.important_features,
        analysis.recommendation_factors
      ]
        .filter((v) => v != null)
        .map(toText)
        .join(' ')
    );


    // --------------------------------
    // 4. 대상 기기
    // --------------------------------
    if (deviceKeywords.length > 0) {
      const hit = deviceKeywords.find((keyword) =>
        targetingText.includes(compact(keyword))
      );

      if (!hit) {
        matched = false;
      } else {
        matchReasons.push(
          `대상 기기 관심 조건 충족 (${hit})`
        );
      }
    }


    // --------------------------------
    // 5. 관심 키워드
    // --------------------------------
    if (interestKeywords.length > 0) {
      const hit = interestKeywords.find((keyword) =>
        targetingText.includes(compact(keyword))
      );

      if (!hit) {
        matched = false;
      } else {
        matchReasons.push(
          `관심 조건 충족 (${hit})`
        );
      }
    }


    // --------------------------------
    // 6. 선호 브랜드
    // --------------------------------
    if (brandKeywords.length > 0) {
      const brandText = [
        customer.preferred_brand,
        analysis.preferred_product_group
      ]
        .filter(Boolean)
        .join(' ');

      if (!containsAny(brandText, brandKeywords)) {
        matched = false;
      } else {
        matchReasons.push('선호 브랜드 조건 충족');
      }
    }


    // --------------------------------
    // 7. 대상 요금제
    // --------------------------------
    if (planKeywords.length > 0) {
      if (!containsAny(customer.current_plan, planKeywords)) {
        matched = false;
      } else {
        matchReasons.push('대상 요금제 조건 충족');
      }
    }
  }


  if (!matched) {
    continue;
  }


  // --------------------------------
  // 최종 대상 고객
  // --------------------------------
  results.push({
    json: {
      customer_id: customer.customer_id,
      customer_name: customer.customer_name,
      phone: customer.phone,

      schedule_type: 'promotion',

      reference_date: promotion.valid_from ?? null,

      contact_reason:
        `${promotion.file_name || '프로모션'} 안내`,

      document_id: promotion.document_id ?? null,
      store_id: promotion.store_id ?? null,

      consultation_id: null,

      match_reasons: matchReasons,

      eligibility_notes:
        Array.isArray(rules.eligibility_notes)
          ? rules.eligibility_notes
          : []
    }
  });
}

return results;

const items = $input.all();

const seen = new Set();
const results = [];

for (const item of items) {
  const customer = item.json;

  // 필수값 확인
  if (!customer.customer_id) {
    continue;
  }

  if (!customer.document_id) {
    continue;
  }

  if (!customer.schedule_type) {
    continue;
  }

  // 고객 + 프로모션 기준 중복 제거
  const uniqueKey =
    `${customer.document_id}:${customer.customer_id}`;

  if (seen.has(uniqueKey)) {
    continue;
  }

  seen.add(uniqueKey);

  results.push({
    json: {
      customer_id: customer.customer_id,
      customer_name: customer.customer_name ?? null,
      phone: customer.phone ?? null,

      schedule_type: customer.schedule_type,

      reference_date: customer.reference_date ?? null,
      contact_reason: customer.contact_reason ?? null,

      document_id: customer.document_id,

      // null 허용: null이면 전 매장 대상
      store_id: customer.store_id ?? null,

      consultation_id: customer.consultation_id ?? null,

      match_reasons: Array.isArray(customer.match_reasons)
        ? customer.match_reasons
        : [],

      eligibility_notes: Array.isArray(customer.eligibility_notes)
        ? customer.eligibility_notes
        : []
    }
  });
}

return results;

const input = $('Validate Promotion Input').first().json;

return [
  {
    json: {
      success: false,
      feature_id: 'F-05',
      status: 'promotion_not_found',

      document_id: input.document_id ?? null,
      store_id: input.store_id ?? null,

      target_count: 0,
      matches: []
    }
  }
];

const input = $input.first().json;

let rules = input.condition_data;

if (typeof rules === 'string') {
  try {
    rules = JSON.parse(rules);
  } catch {
    throw new Error('condition_data를 JSON으로 변환할 수 없습니다.');
  }
}

if (
  !rules ||
  typeof rules !== 'object' ||
  Array.isArray(rules) ||
  Object.keys(rules).length === 0
) {
  throw new Error('사용 가능한 condition_data가 없습니다.');
}

return [
  {
    json: {
      document_id: input.document_id ?? null,
      store_id: input.store_id ?? null,
      valid_from: input.valid_from ?? null,
      valid_until: input.valid_until ?? null,

      output: rules,
      source: 'condition_data'
    }
  }
];

const promotion = $('프로모션 정보 조회').first().json;

const text = $input.all()
  .map((item) =>
    item.json.document?.pageContent ??
    item.json.pageContent ??
    item.json.content ??
    item.json.text ??
    ''
  )
  .filter((value) => typeof value === 'string' && value.trim() !== '')
  .join('\n\n');

return [
  {
    json: {
      ...promotion,
      promotion_condition_text: text || null,
      condition_source: 'rag'
    }
  }
];

const input = $input.first().json;
const promotion = $('프로모션 정보 조회').first().json;

const rules = input.output ?? {};

if (
  !rules ||
  typeof rules !== 'object' ||
  Array.isArray(rules) ||
  Object.keys(rules).length === 0
) {
  throw new Error('사용 가능한 타겟팅 규칙이 없습니다.');
}

return [
  {
    json: {
      document_id: promotion.document_id ?? input.document_id ?? null,
      store_id: promotion.store_id ?? input.store_id ?? null,
      valid_from: promotion.valid_from ?? input.valid_from ?? null,
      valid_until: promotion.valid_until ?? input.valid_until ?? null,

      output: rules,

      source: input.source ?? 'rag'
    }
  }
];

const promotion = $('프로모션 정보 조회').first().json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-05',
      status: 'no_target',

      document_id: promotion.document_id ?? null,
      store_id: promotion.store_id ?? null,
      event_name: promotion.file_name ?? null,
      valid_from: promotion.valid_from ?? null,
      valid_until: promotion.valid_until ?? null,

      target_count: 0,
      matches: []
    }
  }
];

const promotion = $('프로모션 정보 조회').first().json;

return [
  {
    json: {
      success: false,
      feature_id: 'F-05',

      status: 'condition_not_found',
      message: '프로모션 대상 조건을 확인할 수 있는 문서 정보가 없습니다.',

      document_id: promotion.document_id ?? null,
      store_id: promotion.store_id ?? null,

      valid_from: promotion.valid_from ?? null,
      valid_until: promotion.valid_until ?? null,

      target_count: 0,
      matches: []
    }
  }
];

const customers = $input.all().map(item => item.json);
const promotion = $('프로모션 정보 조회').first().json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-05',
      status: 'targeted',

      document_id: promotion.document_id ?? null,
      store_id: promotion.store_id ?? null,
      event_name: promotion.file_name ?? null,
      valid_from: promotion.valid_from ?? null,
      valid_until: promotion.valid_until ?? null,

      target_count: customers.length,

      matches: customers.map(customer => ({
        customer_id: customer.customer_id,
        customer_name: customer.customer_name ?? null,
        phone: customer.phone ?? null,
        schedule_type: customer.schedule_type ?? 'promotion',
        reference_date: customer.reference_date ?? null,
        contact_reason: customer.contact_reason ?? null,
        consultation_id: customer.consultation_id ?? null,
        match_reasons: customer.match_reasons ?? [],
        eligibility_notes: customer.eligibility_notes ?? []
      }))
    }
  }
];
